{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Amphotericin B has a mean oral bioavailability of only 4.8 ± 3.8% in rats, similar to reported low human values, providing affirmative threshold-relevant evidence that a highly polar, H-bond-rich natural product can fall well below 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "9-Nitrocamptothecin, a rigid polycyclic lactone natural product, has very low absolute oral bioavailability with high variability, supporting the expectation that the query's complex polar scaffold is unlikely to reach 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Topotecan, another polycyclic lactone-containing natural product, reaches about 44% oral bioavailability in patients, showing that such scaffolds are not inherently below 20%; however, its ionizable amine and lower polarity make it less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low: the query is an extremely polar, poorly permeable polycyclic lactone (logD -1.37, TPSA 149 Å², 10 HBA), and the most threshold-relevant experimental analogues with very low F (amphotericin B, 9-nitrocamptothecin) support F < 20%. Moderate-F analogues are less structurally similar and do not override the coherent physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All available analogues have low Morgan similarity (<0.19), limiting transferability.",
    "No permeability, efflux, or metabolism data specific to the query scaffold.",
    "No formulation or dose-dependent oral PK data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

